    43531566, 43531653, 43531577, 43531562, 37016163, 45769894, 45757474, 
    37016768, 4221495, 43531616, 43531564, 443733, 43530689, 4226121, 
    36712686, 36712687, 43531608, 43531597, 443732, 45757280, 45769906, 
    4177050, 4223463, 43530690, 45769890, 37018728, 45772019, 45769889, 
    37016349, 45770880, 45757392, 45771064, 45757447, 45757446, 45757445, 
    45757444, 45757363, 45772060, 36714116, 45769875, 4130162, 45771072, 
    45770830, 45769905, 45757435, 43531651, 45770881, 4222415, 45769828, 
    376065, 45757450, 45770883, 45757255, 37016354, 43530656, 45769836, 
    443729, 45757278, 37017432, 4063043, 43531010, 4129519, 43530685, 
    45770831, 45757499, 443731, 45770928, 45757075, 45769872, 45769835, 
    36712670, 46274058, 4142579, 45770832, 45773064, 201826, 4230254, 
    4304377, 4321756, 4196141, 4099217, 201530, 4151282, 4099216, 4198296, 
    4193704, 4200875, 4099651, 45766052, 40482801, 45757277, 45757449, 
    443734
  )
  UNION 
  SELECT c.concept_id 
  FROM public.concept c 
  JOIN public.concept_ancestor ca ON c.concept_id = ca.descendant_concept_id 
  AND ca.ancestor_concept_id IN (
    4140466, 43531588, 45769888, 45763582, 37018912, 43531578, 43531559, 
    43531566, 43531653, 43531577, 43531562, 37016163, 45769894, 45757474, 
    37016768, 4221495, 43531616, 43531564, 443733, 43530689, 4226121, 
    36712686, 36712687, 43531608, 43531597, 443732, 45757280, 45769906, 
    4177050, 4223463, 43530690, 45769890, 37018728, 45772019, 45769889, 
    37016349, 45770880, 45757392, 45771064, 45757447, 45757446, 45757445, 
    45757444, 45757363, 45772060, 36714116, 45769875, 4130162, 45771072, 
    45770830, 45769905, 45757435, 43531651, 45770881, 4222415, 45769828, 
    376065, 45757450, 45770883, 45757255, 37016354, 43530656, 45769836, 
    443729, 45757278, 37017432, 4063043, 43531010, 4129519, 43530685, 
    45770831, 45757499, 443731, 45770928, 45757075, 45769872, 45769835, 
    36712670, 46274058, 4142579, 45770832, 45773064, 201826, 4230254, 
    4304377, 4321756, 4196141, 4099217, 201530, 4151282, 4099216, 4198296, 
    4193704, 4200875, 4099651, 45766052, 40482801, 45757277, 45757449, 
    443734
  )
  AND c.invalid_reason IS NULL
),

-- Define T1DM diagnosis codes
T1DM_DX AS (
  SELECT DISTINCT concept_id 
  FROM public.concept 
  WHERE concept_id IN (
    36715571, 45769891, 37016767, 45763585, 4225656, 45773688, 45773576, 
