  FROM public.concept c 
  JOIN public.concept_ancestor ca ON c.concept_id = ca.descendant_concept_id 
  AND ca.ancestor_concept_id IN (
    36715571, 45769891, 37016767, 45763585, 4225656, 45773688, 45773576, 
    45769901, 45771075, 45769902, 45769903, 45769837, 45769832, 45757674, 
    435216, 377821, 37016353, 45769904, 43531565, 37017429, 37016348, 
    45757432, 443592, 201531, 45757393, 45771067, 45769876, 4228112, 
    45757362, 4047906, 4102018, 36717215, 45757073, 439770, 4224254, 
    4143857, 45757535, 37016179, 43530660, 37016180, 4225055, 4224709, 
    45769829, 45769830, 45763583, 45769834, 36713094, 318712, 37018566, 
    4222687, 4222553, 37017431, 4063042, 43531008, 43531009, 45763584, 
    45757604, 200687, 45757266, 4227210, 45771533, 45773567, 45769833, 
    46269764, 4143689, 45769873, 201254, 4099215, 40484648, 4152858, 
    4099214, 443412, 45766051, 45757507, 45769892, 45770902, 45757074
  )
  AND c.invalid_reason IS NULL
),

-- Define T2DM medication codes
T2DM_MED AS (
  SELECT DISTINCT concept_id 
  FROM public.concept 
  WHERE concept_id IN (
    1529331, 1530014, 44816332, 43013884, 43526465, 1594973, 44785829, 
    45774435, 45774751, 1583722, 1597756, 1560171, 1559684, 40239216, 
    40170911, 44506754, 1503297, 1510202, 1502826, 1525215, 1516766, 
    1547504, 40166035, 1580747, 1502809, 1502855, 1515249, 596554, 
    19059796, 19059796, 19001441, 1517998
  )
  UNION 
  SELECT c.concept_id 
  FROM public.concept c 
  JOIN public.concept_ancestor ca ON c.concept_id = ca.descendant_concept_id 
  AND ca.ancestor_concept_id IN (
    1529331, 1530014, 44816332, 43013884, 43526465, 1594973, 44785829, 
    45774435, 45774751, 1583722, 1597756, 1560171, 1559684, 40239216, 
    40170911, 44506754, 1503297, 1510202, 1502826, 1525215, 1516766, 
    1547504, 40166035, 1580747, 1502809, 1502855, 1515249, 596554, 
    19059796, 19059796, 19001441, 1517998
  )
  AND c.invalid_reason IS NULL
),

-- Define T1DM medication codes
T1DM_MED AS (
  SELECT DISTINCT concept_id 
  FROM public.concept 
  WHERE concept_id IN (
    35198096, 1531601, 1567198, 35602717, 1516976, 1502905, 1544838, 
    1588986, 46221581, 1550023, 1513876, 42899447, 19013951, 1590165, 
    1596977, 1586346, 1586369
  )
  UNION 
  SELECT c.concept_id 
  FROM public.concept c 
  JOIN public.concept_ancestor ca ON c.concept_id = ca.descendant_concept_id 
  AND ca.ancestor_concept_id IN (
    35198096, 1531601, 1567198, 35602717, 1516976, 1502905, 1544838, 
    1588986, 46221581, 1550023, 1513876, 42899447, 19013951, 1590165, 
    1596977, 1586346, 1586369
  )
  AND c.invalid_reason IS NULL
)

SELECT DISTINCT p.person_id
FROM public.person p
WHERE
    -- Require T2DM diagnosis
    EXISTS (
        SELECT 1
        FROM public.condition_occurrence c
        WHERE c.person_id = p.person_id
          AND c.condition_concept_id IN (
              SELECT concept_id FROM T2DM_DX
          )
    )

    -- Exclude patients with T1DM diagnosis
    AND NOT EXISTS (
        SELECT 1
        FROM public.condition_occurrence c
        WHERE c.person_id = p.person_id
          AND c.condition_concept_id IN (
              SELECT concept_id FROM T1DM_DX
          )
    )

    -- Require T2DM medication exposure
    AND EXISTS (
        SELECT 1
        FROM public.drug_exposure de
        WHERE de.person_id = p.person_id
          AND de.drug_concept_id IN (
              SELECT concept_id FROM T2DM_MED
          )
    )

ORDER BY p.person_id;